<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/smart_city_v630.php';if(!sc630_enabled()){http_response_code(404);exit('City Services unavailable.');}$u=sc630_require_user();$uid=(int)$u['id'];$flash='';$err='';try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();$id=sc630_create_request($uid,$_POST);header('Location: /complaints.php?id='.$id.'&created=1',true,302);exit;}}catch(Throwable $e){$err=$e->getMessage();}$cats=sc630_municipal_categories();$rows=sc630_user_requests($uid);$detail=!empty($_GET['id'])?sc630_request((int)$_GET['id'],$uid):null;if(isset($_GET['created']))$flash='Your city request has been submitted.';sc630_public_header('City Services & Complaints','Submit and track non-emergency municipal complaints and citizen service requests.');
?>
<main><section class="sc630-subhero municipal"><div class="sc630-shell"><span>CITIZEN SERVICES HUB</span><h1>Report it. Track it. Stay informed.</h1><p>Submit non-emergency complaints, service requests and lost/found notices. Every request receives a trackable reference number.</p><div class="sc630-safety">Emergency? Do not use this form. Call configured emergency services at <b><?=e(sc630_emergency_number())?></b>.</div></div></section><div class="sc630-shell sc630-content-grid"><?php if($flash):?><div class="sc630-alert success full"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="sc630-alert error full"><?=e($err)?></div><?php endif;?>
<section class="sc630-panel"><h2>Submit a City Request</h2><form method="post" class="sc630-form"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><label>Request type<select name="request_type"><option value="complaint">Complaint</option><option value="service_request">Service Request</option><option value="lost_found">Lost & Found</option></select></label><label>Category<select name="category_id"><option value="">Choose category</option><?php foreach($cats as $c):?><option value="<?=(int)$c['id']?>"><?=e(($c['icon']?:'').' '.$c['name'])?></option><?php endforeach;?></select></label><label>Title<input name="title" maxlength="220" required placeholder="Short clear summary"></label><label>Description<textarea name="description" required rows="6" placeholder="Describe what happened, where it is and any useful non-sensitive details."></textarea></label><div class="two"><label>Area<input name="area"></label><label>Priority<select name="priority"><option value="normal">Normal</option><option value="urgent">Urgent non-emergency</option></select></label></div><label>Address / landmark<textarea name="address" rows="2"></textarea></label><div class="two"><label>Latitude<input name="latitude" inputmode="decimal"></label><label>Longitude<input name="longitude" inputmode="decimal"></label></div><button type="button" class="sc630-btn" data-sc-location>Use My Location</button> <button class="sc630-btn primary">Submit Request</button></form></section>
<aside class="sc630-panel"><h2>My Requests</h2><?php if(!$rows):?><p class="empty">No requests submitted yet.</p><?php endif;?><?php foreach($rows as $r):?><a class="sc630-request-card <?=$detail&&(int)$detail['id']===(int)$r['id']?'active':''?>" href="/complaints.php?id=<?=(int)$r['id']?>"><i><?=e($r['category_icon']?:'◫')?></i><span><b><?=e($r['title'])?></b><small><?=e($r['reference_no'])?> · <?=e(ucwords(str_replace('_',' ',$r['status'])))?></small></span><em><?=e($r['priority'])?></em></a><?php endforeach;?></aside>
<?php if($detail):?><section class="sc630-panel full"><div class="sc630-panel-head"><div><small><?=e($detail['reference_no'])?></small><h2><?=e($detail['title'])?></h2></div><span class="sc630-status"><?=e(ucwords(str_replace('_',' ',$detail['status'])))?></span></div><p><?=nl2br(e($detail['description']))?></p><div class="sc630-timeline"><?php foreach($detail['updates'] as $x):?><div><i></i><span><b><?=e(ucwords(str_replace('_',' ',(string)($x['status']?:'update'))))?></b><p><?=e($x['note']?:'Status updated.')?></p><small><?=e(date('d M Y h:i A',strtotime($x['created_at'])))?></small></span></div><?php endforeach;?></div></section><?php endif;?></div></main><?php sc630_public_footer(); ?>
